/* Minimal QR code placeholder.
 * NOTE: Replace with a real QR code generator library (e.g., qrcodejs) for production.
 * This placeholder avoids runtime JS errors if the library isn't present yet.
 */
(function (global) {
  function QRCode(el, text) {
    if (!el) return;
    var pre = document.createElement('pre');
    pre.style.whiteSpace = 'pre-wrap';
    pre.textContent = 'QR code data (install a real QR library to render as QR):\n' + (text || '');
    el.innerHTML = '';
    el.appendChild(pre);
  }
  global.QRCode = global.QRCode || QRCode;
})(window);
